import{_ as c,C as t,o as l,c as d,a3 as n,E as r,j as e,a as i,b as p,w as o,a6 as u}from"./chunks/framework.Ba39LDvt.js";const D=JSON.parse('{"title":"光电子与集成光子","description":"认识上科大的光电探测、集成光子、非线性与量子光芯片以及光计算研究。","frontmatter":{"title":"光电子与集成光子","description":"认识上科大的光电探测、集成光子、非线性与量子光芯片以及光计算研究。"},"headers":[],"relativePath":"research/photonics.md","filePath":"research/photonics.md","lastUpdated":1795525517000}'),A={name:"research/photonics.md"};function B(f,a,g,b,m,_){const s=t("FacultyList"),h=t("CourseTable"),E=t("Mermaid");return l(),d("div",null,[a[1]||(a[1]=n('<h1 id="光电子与集成光子" tabindex="-1">光电子与集成光子 <a class="header-anchor" href="#光电子与集成光子" aria-label="Permalink to &quot;光电子与集成光子&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>光电子学研究光与电子系统之间的转换，集成光子学（Integrated Photonics）则把波导、调制器、谐振器等光学结构集成到芯片上。它可以服务于高速互联、光通信、激光雷达、精密测量，也能探索光计算与量子信息。这里的“芯片”不一定使用纯硅材料，不同材料平台的光学性能、制造条件和集成方式差异很大。</p><p>核心研究问题包括：</p><ul><li>如何在探测速度、响应度、噪声与工作电压之间取得平衡？</li><li>光源、波导、调制与探测怎样在材料及封装层面集成？</li><li>如何减小传播损耗、耦合损耗和温度漂移？</li><li>怎样利用非线性效应实现频率转换、光频梳或量子光源？</li><li>光计算的优势能否覆盖调制、探测、校准和数据转换的系统开销？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大在这一方向有从器件到系统的多条公开路线。陈佰乐关注雪崩光电二极管、高速光电探测芯片、III-V 族光子芯片以及硅基集成激光器和探测器；王成的方向包括人工智能光计算芯片、半导体激光器、激光通信与激光雷达。邹毅的 EZLab 侧重集成光子学、光互联、光电融合芯片与微纳光子学。</p><p>陆娟娟的 iNQuP 实验室研究光子集成电路、非线性光子学和量子光子学；中心介绍材料进一步列出低损耗光芯片、光频梳、非线性频率转换和量子光源。曲俞睿关注光计算、光芯片、光子智能感知与微纳光子学；周平强的公开方向包含光电混合计算，可作为连接器件与设计方法的另一入口。具体课题请继续阅读卡片中的主页与近期论文。</p>',8)),r(s,{dir:"photonics"}),a[2]||(a[2]=e("h2",{id:"相关上科大课程",tabindex:"-1"},[i("相关上科大课程 "),e("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),a[3]||(a[3]=e("p",null,"先补电磁学与物理光学，再按器件、导波、非线性或计算兴趣选择进阶课程；表中按领域列出计划课程，实际开课以教务系统为准。",-1)),r(h,{area:"photonics"}),a[4]||(a[4]=e("h2",{id:"知识前置",tabindex:"-1"},[i("知识前置 "),e("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),a[5]||(a[5]=e("p",null,"这是学习建议图，不是正式先修表；量子光学路线还需要进一步学习量子力学。",-1)),(l(),p(u,null,{default:o(()=>[r(E,{id:"mermaid-64",class:"mermaid",graph:"graph%20TD%0A%20%20A%5B%22%E6%95%B0%E5%AD%A6%E4%B8%8E%E6%99%AE%E9%80%9A%E7%89%A9%E7%90%86%22%5D%20--%3E%20B%5B%22EE130%20%E7%94%B5%E7%A3%81%E5%AD%A6%22%5D%0A%20%20B%20--%3E%20C%5B%22EE131H%20%E7%89%A9%E7%90%86%E5%85%89%E5%AD%A6%22%5D%0A%20%20B%20--%3E%20D%5B%22EE120%20%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E5%9F%BA%E7%A1%80%22%5D%0A%20%20C%20--%3E%20E%5B%22EE290C%20%E5%AF%BC%E6%B3%A2%E5%85%89%E5%AD%A6%22%5D%0A%20%20C%20--%3E%20F%5B%22EE2212%20%E7%BA%B3%E7%B1%B3%E5%85%89%E5%AD%90%E5%AD%A6%E5%8F%8A%E5%99%A8%E4%BB%B6%22%5D%0A%20%20D%20--%3E%20G%5B%22EE222%20%E5%85%89%E7%94%B5%E5%99%A8%E4%BB%B6II%22%5D%0A%20%20C%20--%3E%20H%5B%22EE239B%20%E9%9D%9E%E7%BA%BF%E6%80%A7%E5%85%89%E5%AD%A6%E5%8F%8A%E5%85%B6%E5%99%A8%E4%BB%B6%22%5D%0A%20%20E%20--%3E%20I%5B%22%E9%9B%86%E6%88%90%E5%85%89%E5%AD%90%E4%B8%8E%E5%85%89%E7%94%B5%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20F%20--%3E%20I%0A%20%20G%20--%3E%20I%0A%20%20H%20--%3E%20I%0A%20%20I%20--%3E%20J%5B%22SI362%20%E5%85%89%E8%AE%A1%E7%AE%97%E4%B8%8E%E5%85%89%E7%A5%9E%E7%BB%8F%E7%BD%91%E7%BB%9C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：MIT、Stanford、UCSB，以及清华、浙江大学、中科院半导体所等都有光电子或集成光子相关研究；检索时要区分材料器件、光路设计与系统应用。</li><li><strong>产业参照</strong>：Intel 的硅光、台积电的光电集成相关技术、Coherent 的光电子器件，展示了不同的产业切入点；并非本校合作关系清单。</li><li><strong>会议与期刊</strong>：OFC 偏光通信与互联，CLEO 覆盖激光与光电子；Optica、Light: Science &amp; Applications、ACS Photonics、Journal of Lightwave Technology（JLT）是常见阅读入口。</li></ul><p>比较论文时要看工作波长、材料平台、片上还是离片光源，以及损耗与功耗是否把封装和控制电路算进去。光学矩阵运算的速度不能直接当成完整 AI 系统的吞吐率。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/device">器件自学</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/foundations">基础自学</a>：补电磁场、半导体与数学基础。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/ai-hardware">AI 硬件自学</a>：理解光计算面向的工作负载与系统指标。</li><li><a href="https://ocw.mit.edu/" target="_blank" rel="noreferrer">MIT OpenCourseWare</a>：检索光学、电磁场与半导体相关公开课程。</li><li><a href="https://www.optica.org/" target="_blank" rel="noreferrer">Optica</a> 与 <a href="https://www.ofcconference.org/" target="_blank" rel="noreferrer">OFC</a>：了解领域术语、会议主题和教育资源。</li></ul><p>起步时可选一个环形谐振器或光电探测器，分别画出结构、输入输出量和关键损耗项。先回答“它在系统中替代什么”，再考虑复杂的片上系统。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎相关课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a> 补充“组里在做什么”、公开的光学仿真与测量入门建议，以及进组前适合准备的基础知识。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/chenbl/main.htm" target="_blank" rel="noreferrer">陈佰乐学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/wangcheng1/main.htm" target="_blank" rel="noreferrer">王成学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/zouyi/main.htm" target="_blank" rel="noreferrer">邹毅学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/lujj/main.htm" target="_blank" rel="noreferrer">陆娟娟学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/quyr/main.htm" target="_blank" rel="noreferrer">曲俞睿学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/zhoupq/main.htm" target="_blank" rel="noreferrer">周平强学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年方向介绍，不作为当前招生依据。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：课程信息以最新公布为准。</li></ul>',10))])}const C=c(A,[["render",B]]);export{D as __pageData,C as default};
